using Dapper;
using Sigov.Application.Commercial;
using Sigov.Application.Common;
using Sigov.Domain.Comercial;
using Sigov.Infrastructure.Persistence.Dapper;
namespace Sigov.Infrastructure.Commercial;
public sealed class CommercialRepository(NpgsqlConnectionFactory factory,ICommercialPersonalDataProtector protector):ICommercialRepository
{
 public async Task<PagedResult<ClienteResumoDto>> ListarClientesAsync(Guid t,ClienteFiltro f,CancellationToken ct){var p=Math.Max(1,f.Pagina);var s=Math.Clamp(f.TamanhoPagina,1,100);const string q="select count(*) from sigov.enterprise_cliente where tenant_id=@t and (@all or not is_deleted) and (not @has or nome ilike @term);select id,nome,documento_masked DocumentoMascarado,email_masked EmailMascarado,telefone_masked TelefoneMascarado,status,version from sigov.enterprise_cliente where tenant_id=@t and (@all or not is_deleted) and (not @has or nome ilike @term) order by nome,id offset @off limit @s";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,all=f.Inativos,has=!string.IsNullOrWhiteSpace(f.Busca),term=$"%{f.Busca}%",off=(p-1)*s,s},cancellationToken:ct));var total=await m.ReadSingleAsync<long>();return new((await m.ReadAsync<ClienteResumoDto>()).AsList(),p,s,total);}
 public async Task<ClienteDetalheDto?> ObterClienteAsync(Guid t,Guid id,bool personal,CancellationToken ct){const string q="select id,nome,nome_fantasia NomeFantasia,tipo_pessoa TipoPessoa,segmento,origem,documento_protegido Documento,email_protegido Email,telefone_protegido Telefone,status,version from sigov.enterprise_cliente where tenant_id=@t and id=@id and not is_deleted";await using var c=factory.CreateConnection();var x=await c.QuerySingleOrDefaultAsync<ClienteDetalheDto>(new CommandDefinition(q,new{t,id},cancellationToken:ct));return x is null?null:x with{Documento=personal?protector.Unprotect(x.Documento):protector.MaskDocument(protector.Unprotect(x.Documento)),Email=personal?protector.Unprotect(x.Email):protector.MaskEmail(protector.Unprotect(x.Email)),Telefone=personal?protector.Unprotect(x.Telefone):protector.MaskPhone(protector.Unprotect(x.Telefone))};}
 public async Task<Guid> CriarClienteAsync(Guid t,Guid u,CriarClienteRequest r,string corr,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Nome))throw new CommercialRuleException("Nome é obrigatório.");var id=Guid.NewGuid();const string q="insert into sigov.enterprise_cliente(id,tenant_id,codigo,nome,tipo_pessoa,nome_fantasia,segmento,origem,documento_hash,documento_protegido,email_protegido,telefone_protegido,documento_masked,email_masked,telefone_masked,responsavel_usuario_id,status,created_by,updated_by,correlation_id) values(@id,@t,@cod,@Nome,@TipoPessoa,@NomeFantasia,@Segmento,@Origem,@dh,@dp,@ep,@tp,@dm,@em,@tm,@ResponsavelUsuarioId,'ATIVO',@us,@us,@corr)";await using var c=factory.CreateConnection();await c.ExecuteAsync(new CommandDefinition(q,new{id,t,cod=$"CLI-{id:N}",r.Nome,r.TipoPessoa,r.NomeFantasia,r.Segmento,r.Origem,dh=protector.Hash(r.Documento),dp=protector.Protect(r.Documento),ep=protector.Protect(r.Email),tp=protector.Protect(r.Telefone),dm=protector.MaskDocument(r.Documento),em=protector.MaskEmail(r.Email),tm=protector.MaskPhone(r.Telefone),r.ResponsavelUsuarioId,us=u.ToString(),corr},cancellationToken:ct));return id;}
 public async Task<PagedResult<LeadResumoDto>> ListarLeadsAsync(Guid t,int p,int s,string? busca,CancellationToken ct){p=Math.Max(1,p);s=Math.Clamp(s,1,100);const string q="select count(*) from sigov.enterprise_lead where tenant_id=@t and not is_deleted and (not @has or nome ilike @term);select id,nome,status,origem,pontuacao,proximo_contato_em ProximoContatoEm,version from sigov.enterprise_lead where tenant_id=@t and not is_deleted and (not @has or nome ilike @term) order by created_at desc offset @off limit @s";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,has=!string.IsNullOrWhiteSpace(busca),term=$"%{busca}%",off=(p-1)*s,s},cancellationToken:ct));var total=await m.ReadSingleAsync<long>();return new((await m.ReadAsync<LeadResumoDto>()).AsList(),p,s,total);}
 public async Task<Guid> CriarLeadAsync(Guid t,Guid u,CriarLeadRequest r,string corr,CancellationToken ct){var id=Guid.NewGuid();const string q="insert into sigov.enterprise_lead(id,tenant_id,codigo,nome,status,origem,interesse,proximo_contato_em,responsavel_usuario_id,documento_hash,documento_protegido,email_protegido,telefone_protegido,documento_masked,email_masked,telefone_masked,created_by,updated_by,correlation_id) values(@id,@t,@cod,@Nome,'NOVO',@Origem,@Interesse,@ProximoContatoEm,@ResponsavelUsuarioId,@dh,@dp,@ep,@tp,@dm,@em,@tm,@us,@us,@corr)";await using var c=factory.CreateConnection();await c.ExecuteAsync(new CommandDefinition(q,new{id,t,cod=$"LEAD-{id:N}",r.Nome,r.Origem,r.Interesse,r.ProximoContatoEm,r.ResponsavelUsuarioId,dh=protector.Hash(r.Documento),dp=protector.Protect(r.Documento),ep=protector.Protect(r.Email),tp=protector.Protect(r.Telefone),dm=protector.MaskDocument(r.Documento),em=protector.MaskEmail(r.Email),tm=protector.MaskPhone(r.Telefone),us=u.ToString(),corr},cancellationToken:ct));return id;}
 public async Task<ConversaoLeadDto> ConverterLeadAsync(Guid t,Guid u,Guid id,ConverterLeadRequest r,string corr,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var lead=await c.QuerySingleOrDefaultAsync<(string Status,string Nome,string? Documento,string? Email,string? Telefone)>(new CommandDefinition("select status,nome,documento_protegido Documento,email_protegido Email,telefone_protegido Telefone from sigov.enterprise_lead where tenant_id=@t and id=@id and not is_deleted for update",new{t,id},tx,cancellationToken:ct));if(lead==default)throw new CommercialNotFoundException("Lead não encontrado.");CommercialRules.PodeConverter(Enum.Parse<LeadStatus>(lead.Status.Replace("_", ""),true));var cid=r.ClienteId??Guid.NewGuid();if(!r.ClienteId.HasValue)await c.ExecuteAsync(new CommandDefinition("insert into sigov.enterprise_cliente(id,tenant_id,codigo,nome,tipo_pessoa,status,documento_protegido,email_protegido,telefone_protegido,created_by,updated_by,correlation_id) values(@cid,@t,@cod,@nome,'J','ATIVO',@Documento,@Email,@Telefone,@us,@us,@corr)",new{cid,t,cod=$"CLI-{cid:N}",nome=lead.Nome,lead.Documento,lead.Email,lead.Telefone,us=u.ToString(),corr},tx,cancellationToken:ct));var oid=Guid.NewGuid();await c.ExecuteAsync(new CommandDefinition("insert into sigov.enterprise_oportunidade(id,tenant_id,codigo,nome,titulo,status,cliente_id,lead_id,fase,valor_estimado,probabilidade,previsao_fechamento,created_by,updated_by,correlation_id) values(@oid,@t,@cod,@TituloOportunidade,@TituloOportunidade,'ABERTA',@cid,@id,'PROSPECCAO',@ValorEstimado,@Probabilidade,@PrevisaoFechamento,@us,@us,@corr);update sigov.enterprise_lead set status='CONVERTIDO',cliente_convertido_id=@cid,oportunidade_convertida_id=@oid,convertido_em=now(),version=version+1,updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@Version;insert into sigov.enterprise_status_historico(tenant_id,entidade_tipo,entidade_id,status_anterior,status_novo,created_by,correlation_id) values(@t,'LEAD',@id,@status,'CONVERTIDO',@us,@corr)",new{oid,t,cod=$"OP-{oid:N}",r.TituloOportunidade,cid,id,r.ValorEstimado,r.Probabilidade,r.PrevisaoFechamento,us=u.ToString(),corr,r.Version,status=lead.Status},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new(cid,oid);}
 public async Task<PagedResult<OportunidadeResumoDto>> ListarOportunidadesAsync(Guid t,int p,int s,string? fase,string? busca,CancellationToken ct){p=Math.Max(1,p);s=Math.Clamp(s,1,100);const string q="select count(*) from sigov.enterprise_oportunidade o where o.tenant_id=@t and not o.is_deleted and (not @hf or o.fase=@fase) and (not @hb or o.titulo ilike @term);select o.id,o.titulo,o.fase,coalesce(c.nome,'Lead') Cliente,o.valor_estimado ValorEstimado,o.probabilidade,o.previsao_fechamento PrevisaoFechamento,o.version from sigov.enterprise_oportunidade o left join sigov.enterprise_cliente c on c.tenant_id=o.tenant_id and c.id=o.cliente_id where o.tenant_id=@t and not o.is_deleted and (not @hf or o.fase=@fase) and (not @hb or o.titulo ilike @term) order by o.previsao_fechamento nulls last,o.id offset @off limit @s";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,hf=!string.IsNullOrWhiteSpace(fase),fase=fase?.ToUpperInvariant(),hb=!string.IsNullOrWhiteSpace(busca),term=$"%{busca}%",off=(p-1)*s,s},cancellationToken:ct));var total=await m.ReadSingleAsync<long>();return new((await m.ReadAsync<OportunidadeResumoDto>()).AsList(),p,s,total);}
 public async Task MoverOportunidadeAsync(Guid t,Guid u,Guid id,MoverOportunidadeRequest r,string corr,CancellationToken ct){if(!Enum.TryParse<OportunidadeFase>(r.Fase.Replace("_", ""),true,out var nova))throw new CommercialRuleException("Fase inválida.");CommercialRules.ValidarMovimento(nova,r.Motivo);await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var antiga=await c.ExecuteScalarAsync<string?>(new CommandDefinition("select fase from sigov.enterprise_oportunidade where tenant_id=@t and id=@id and not is_deleted for update",new{t,id},tx,cancellationToken:ct))??throw new CommercialNotFoundException("Oportunidade não encontrada.");var affected=await c.ExecuteAsync(new CommandDefinition("update sigov.enterprise_oportunidade set fase=@fase,motivo_perda=@Motivo,ganho_em=case when @fase='GANHA' then now() else ganho_em end,perdido_em=case when @fase='PERDIDA' then now() else perdido_em end,version=version+1,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@Version;insert into sigov.enterprise_status_historico(tenant_id,entidade_tipo,entidade_id,status_anterior,status_novo,observacao,created_by,correlation_id) values(@t,'OPORTUNIDADE',@id,@antiga,@fase,@Observacao,@us,@corr)",new{t,id,fase=r.Fase.ToUpperInvariant(),r.Motivo,r.Observacao,r.Version,antiga,us=u.ToString(),corr},tx,cancellationToken:ct));if(affected<2)throw new CommercialConflictException("Versão desatualizada.");await tx.CommitAsync(ct);}
 public async Task<PagedResult<PropostaResumoDto>> ListarPropostasAsync(Guid t,int p,int s,CancellationToken ct){p=Math.Max(1,p);s=Math.Clamp(s,1,100);const string q="select count(*) from sigov.enterprise_proposta where tenant_id=@t and not is_deleted;select p.id,p.numero,c.nome Cliente,p.status,p.validade_em ValidadeEm,p.total,p.version from sigov.enterprise_proposta p join sigov.enterprise_cliente c on c.tenant_id=p.tenant_id and c.id=p.cliente_id where p.tenant_id=@t and not p.is_deleted order by p.created_at desc offset @off limit @s";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,off=(p-1)*s,s},cancellationToken:ct));var total=await m.ReadSingleAsync<long>();return new((await m.ReadAsync<PropostaResumoDto>()).AsList(),p,s,total);}
 public async Task<PropostaDetalheDto?> ObterPropostaAsync(Guid t,Guid id,CancellationToken ct){const string q="select id,numero,cliente_id ClienteId,oportunidade_id OportunidadeId,status,validade_em ValidadeEm,subtotal,desconto,acrescimo,total,condicoes_pagamento CondicoesPagamento,observacao,version from sigov.enterprise_proposta where tenant_id=@t and id=@id and not is_deleted;select id,produto_id ProdutoId,descricao,unidade,quantidade,valor_unitario ValorUnitario,desconto,total,ordem,version from sigov.enterprise_proposta_item where tenant_id=@t and proposta_id=@id and not is_deleted order by ordem,id";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,id},cancellationToken:ct));var h=await m.ReadSingleOrDefaultAsync<PropostaDetalheDto>();if(h is null)return null;return h with{Itens=(await m.ReadAsync<PropostaItemDto>()).AsList()};}
 public async Task<Guid> CriarPropostaAsync(Guid t,Guid u,CriarPropostaRequest r,string corr,CancellationToken ct){var itens=r.Itens.Select(x=>new PropostaItem(x.ProdutoId,x.Descricao,x.Unidade,x.Quantidade,x.ValorUnitario,x.Desconto,x.Ordem)).ToArray();var calc=CommercialRules.CalcularProposta(itens,r.Desconto,r.Acrescimo);var id=Guid.NewGuid();await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var sequencial=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.enterprise_numeracao_comercial(tenant_id,tipo,ano,ultimo_numero) values(@t,'PROPOSTA',extract(year from current_date)::int,1) on conflict(tenant_id,tipo,ano) do update set ultimo_numero=sigov.enterprise_numeracao_comercial.ultimo_numero+1,updated_at=now() returning ultimo_numero",new{t},tx,cancellationToken:ct));var numero=$"PROP-{DateTime.UtcNow:yyyy}-{sequencial:000000}";await c.ExecuteAsync(new CommandDefinition("insert into sigov.enterprise_proposta(id,tenant_id,codigo,nome,numero,cliente_id,oportunidade_id,status,validade_em,subtotal,desconto,acrescimo,total,condicoes_pagamento,observacao,created_by,updated_by,correlation_id) values(@id,@t,@numero,@numero,@numero,@ClienteId,@OportunidadeId,'RASCUNHO',@ValidadeEm,@Subtotal,@Desconto,@Acrescimo,@Total,@CondicoesPagamento,@Observacao,@us,@us,@corr)",new{id,t,numero,r.ClienteId,r.OportunidadeId,r.ValidadeEm,calc.Subtotal,r.Desconto,r.Acrescimo,calc.Total,r.CondicoesPagamento,r.Observacao,us=u.ToString(),corr},tx,cancellationToken:ct));foreach(var i in itens)await c.ExecuteAsync(new CommandDefinition("insert into sigov.enterprise_proposta_item(tenant_id,codigo,nome,proposta_id,produto_id,descricao,unidade,quantidade,valor_unitario,desconto,total,ordem,status,created_by,updated_by,correlation_id) values(@t,gen_random_uuid()::text,@Descricao,@id,@ProdutoId,@Descricao,@Unidade,@Quantidade,@ValorUnitario,@Desconto,@Total,@Ordem,'ATIVO',@us,@us,@corr)",new{t,id,i.ProdutoId,i.Descricao,i.Unidade,i.Quantidade,i.ValorUnitario,i.Desconto,i.Total,i.Ordem,us=u.ToString(),corr},tx,cancellationToken:ct));await tx.CommitAsync(ct);return id;}
 public Task EmitirPropostaAsync(Guid t,Guid u,Guid id,long v,string corr,CancellationToken ct)=>TransitionProposal(t,u,id,v,"RASCUNHO","EMITIDA",corr,ct);
 public Task AprovarPropostaAsync(Guid t,Guid u,Guid id,long v,string corr,CancellationToken ct)=>TransitionProposal(t,u,id,v,"EMITIDA","APROVADA",corr,ct);
 private async Task TransitionProposal(Guid t,Guid u,Guid id,long v,string from,string to,string corr,CancellationToken ct){await using var c=factory.CreateConnection();var n=await c.ExecuteAsync(new CommandDefinition("update sigov.enterprise_proposta p set status=@to,emitida_em=case when @to='EMITIDA' then now() else emitida_em end,decidida_em=case when @to='APROVADA' then now() else decidida_em end,version=version+1,updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@v and status=@from and exists(select 1 from sigov.enterprise_proposta_item i where i.tenant_id=p.tenant_id and i.proposta_id=p.id and not i.is_deleted)",new{t,id,v,from,to,us=u.ToString(),corr},cancellationToken:ct));if(n!=1)throw new CommercialConflictException("Transição inválida, proposta sem itens ou versão desatualizada.");}
 public async Task<PedidoDetalheDto> GerarPedidoAsync(Guid t,Guid u,Guid pid,string key,string corr,CancellationToken ct){if(string.IsNullOrWhiteSpace(key))throw new CommercialRuleException("Idempotency-Key é obrigatório.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var existing=await c.QuerySingleOrDefaultAsync<PedidoDetalheDto>(new CommandDefinition("select p.id,p.numero,p.proposta_id PropostaId,p.cliente_id ClienteId,p.status,p.subtotal,p.desconto,p.total,p.requer_ordem_servico RequerOrdemServico,p.ordem_servico_id OrdemServicoId,p.version from sigov.enterprise_operacao_idempotente i join sigov.enterprise_pedido_venda p on p.tenant_id=i.tenant_id and p.id=i.aggregate_id where i.tenant_id=@t and i.operacao='GERAR_PEDIDO' and i.chave=@key",new{t,key},tx,cancellationToken:ct));if(existing is not null){await tx.CommitAsync(ct);return existing;}var prop=await c.QuerySingleOrDefaultAsync<(Guid ClienteId,string Status,decimal Subtotal,decimal Desconto,decimal Total,Guid? OportunidadeId)>(new CommandDefinition("select cliente_id ClienteId,status,subtotal,desconto,total,oportunidade_id OportunidadeId from sigov.enterprise_proposta where tenant_id=@t and id=@pid and not is_deleted for update",new{t,pid},tx,cancellationToken:ct));if(prop==default)throw new CommercialNotFoundException("Proposta não encontrada.");if(prop.Status!="APROVADA")throw new CommercialConflictException("Somente proposta aprovada gera pedido.");var id=Guid.NewGuid();var numero=$"PED-{DateTime.UtcNow:yyyy}-{id.ToString()[..6]}";await c.ExecuteAsync(new CommandDefinition("insert into sigov.enterprise_pedido_venda(id,tenant_id,codigo,nome,numero,proposta_id,cliente_id,status,subtotal,desconto,total,created_by,updated_by,correlation_id) values(@id,@t,@numero,@numero,@numero,@pid,@ClienteId,'ABERTO',@Subtotal,@Desconto,@Total,@us,@us,@corr);insert into sigov.enterprise_pedido_venda_item(tenant_id,codigo,nome,pedido_id,produto_id,descricao,unidade,quantidade,valor_unitario,desconto,total,reservar_estoque,status,created_by,updated_by,correlation_id) select tenant_id,gen_random_uuid()::text,descricao,@id,produto_id,descricao,unidade,quantidade,valor_unitario,desconto,total,produto_id is not null,'ATIVO',@us,@us,@corr from sigov.enterprise_proposta_item where tenant_id=@t and proposta_id=@pid and not is_deleted;update sigov.enterprise_proposta set pedido_id=@id where tenant_id=@t and id=@pid;insert into sigov.enterprise_operacao_idempotente(tenant_id,operacao,chave,aggregate_id,created_by,correlation_id) values(@t,'GERAR_PEDIDO',@key,@id,@us,@corr)",new{id,t,numero,pid,prop.ClienteId,prop.Subtotal,prop.Desconto,prop.Total,us=u.ToString(),corr},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new(id,numero,pid,prop.ClienteId,"ABERTO",prop.Subtotal,prop.Desconto,prop.Total,false,null,1);}
 public async Task<PagedResult<PedidoResumoDto>> ListarPedidosAsync(Guid t,int p,int s,CancellationToken ct){p=Math.Max(1,p);s=Math.Clamp(s,1,100);const string q="select count(*) from sigov.enterprise_pedido_venda where tenant_id=@t and not is_deleted;select p.id,p.numero,c.nome Cliente,p.status,p.total,p.previsao_entrega PrevisaoEntrega,p.version from sigov.enterprise_pedido_venda p join sigov.enterprise_cliente c on c.tenant_id=p.tenant_id and c.id=p.cliente_id where p.tenant_id=@t and not p.is_deleted order by p.created_at desc offset @off limit @s";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,off=(p-1)*s,s},cancellationToken:ct));var total=await m.ReadSingleAsync<long>();return new((await m.ReadAsync<PedidoResumoDto>()).AsList(),p,s,total);}
 public async Task ConfirmarPedidoAsync(Guid t,Guid u,Guid id,long v,string key,string corr,CancellationToken ct)
 {
  await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);
  var replay=await c.ExecuteScalarAsync<Guid?>(new CommandDefinition("select recurso_id from sigov.enterprise_comercial_idempotencia where tenant_id=@t and operacao='CONFIRMAR_PEDIDO' and chave=@key",new{t,key},tx,cancellationToken:ct));
  if(replay.HasValue){if(replay.Value!=id)throw new CommercialConflictException("Idempotency-Key já utilizada em outro pedido.");await tx.CommitAsync(ct);return;}
  var order=await c.QuerySingleOrDefaultAsync<(string Status,long Version)>(new CommandDefinition("select status,version from sigov.enterprise_pedido_venda where tenant_id=@t and id=@id and not is_deleted for update",new{t,id},tx,cancellationToken:ct));
  if(order==default)throw new CommercialNotFoundException("Pedido não encontrado.");
  if(order.Status=="CONFIRMADO")throw new CommercialConflictException("Pedido já confirmado; reutilize a Idempotency-Key original.");
  if(order.Status!="ABERTO")throw new CommercialConflictException("Pedido não pode ser confirmado no status atual.");
  if(order.Version!=v)throw new CommercialConflictException("Pedido foi alterado por outro usuário.");
  var falta=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.enterprise_pedido_venda_item i left join sigov.enterprise_estoque_saldo s on s.tenant_id=i.tenant_id and s.produto_id=i.produto_id and not s.is_deleted where i.tenant_id=@t and i.pedido_id=@id and i.reservar_estoque and not i.is_deleted and coalesce(s.quantidade,0)<i.quantidade)",new{t,id},tx,cancellationToken:ct));
  if(falta)throw new CommercialConflictException("Estoque insuficiente para confirmar o pedido.");
  await c.ExecuteAsync(new CommandDefinition("insert into sigov.enterprise_estoque_reserva(tenant_id,pedido_id,pedido_item_id,produto_id,quantidade,created_by,updated_by,correlation_id) select tenant_id,@id,id,produto_id,quantidade,@us,@us,@corr from sigov.enterprise_pedido_venda_item where tenant_id=@t and pedido_id=@id and reservar_estoque and not is_deleted on conflict (tenant_id,pedido_item_id) where not is_deleted do nothing",new{t,id,us=u.ToString(),corr},tx,cancellationToken:ct));
  var affected=await c.ExecuteAsync(new CommandDefinition("update sigov.enterprise_pedido_venda set status='CONFIRMADO',confirmado_em=now(),version=version+1,updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and status='ABERTO' and version=@v",new{t,id,v,us=u.ToString(),corr},tx,cancellationToken:ct));
  if(affected!=1)throw new CommercialConflictException("Confirmação concorrente detectada.");
  await c.ExecuteAsync(new CommandDefinition("insert into sigov.enterprise_comercial_idempotencia(tenant_id,operacao,chave,recurso_id,created_by,correlation_id) values(@t,'CONFIRMAR_PEDIDO',@key,@id,@us,@corr)",new{t,key,id,us=u.ToString(),corr},tx,cancellationToken:ct));
  await tx.CommitAsync(ct);
 }
 public async Task<ComercialDashboardDto> ObterDashboardAsync(Guid t,DateOnly inicio,DateOnly fim,CancellationToken ct){const string q="select count(*) filter(where created_at>=@inicio and created_at<@fim) LeadsNovos,count(*) filter(where status='QUALIFICADO' and updated_at>=@inicio and updated_at<@fim) LeadsQualificados,count(*) filter(where status='CONVERTIDO' and updated_at>=@inicio and updated_at<@fim) Convertidos from sigov.enterprise_lead where tenant_id=@t and not is_deleted;select count(*) filter(where fase not in('GANHA','PERDIDA')) Abertas,coalesce(sum(valor_estimado) filter(where fase not in('GANHA','PERDIDA')),0) Pipeline,coalesce(sum(valor_estimado*probabilidade/100.0) filter(where fase not in('GANHA','PERDIDA')),0) Ponderado from sigov.enterprise_oportunidade where tenant_id=@t and not is_deleted;select count(*) filter(where status='EMITIDA') Emitidas,count(*) filter(where status='APROVADA') Aprovadas,coalesce(sum(total) filter(where status='APROVADA'),0) Valor from sigov.enterprise_proposta where tenant_id=@t and not is_deleted and created_at>=@inicio and created_at<@fim;select count(*) Quantidade,coalesce(avg(total),0) Ticket from sigov.enterprise_pedido_venda where tenant_id=@t and not is_deleted and status='CONFIRMADO' and confirmado_em>=@inicio and confirmado_em<@fim;select fase,count(*) Quantidade from sigov.enterprise_oportunidade where tenant_id=@t and not is_deleted group by fase";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,inicio=inicio.ToDateTime(TimeOnly.MinValue),fim=fim.AddDays(1).ToDateTime(TimeOnly.MinValue)},cancellationToken:ct));var l=await m.ReadSingleAsync<(int LeadsNovos,int LeadsQualificados,int Convertidos)>();var o=await m.ReadSingleAsync<(int Abertas,decimal Pipeline,decimal Ponderado)>();var p=await m.ReadSingleAsync<(int Emitidas,int Aprovadas,decimal Valor)>();var e=await m.ReadSingleAsync<(int Quantidade,decimal Ticket)>();var funil=(await m.ReadAsync<(string Fase,int Quantidade)>()).ToDictionary(x=>x.Fase,x=>x.Quantidade);return new(l.LeadsNovos,l.LeadsQualificados,l.LeadsNovos==0?0:100m*l.Convertidos/l.LeadsNovos,o.Abertas,o.Pipeline,o.Ponderado,p.Emitidas,p.Aprovadas,p.Valor,e.Quantidade,e.Ticket,funil);}
